package org.cgse.core;
import java.math.BigInteger;import java.util.*;
public class ProbedCoverProbe{
 static BigInteger b(long n){return BigInteger.valueOf(n);}static boolean pass(ExactLinearProgram.Constraint r,BigInteger[] x){BigInteger sum=BigInteger.ZERO;for(var e:r.terms().entrySet())sum=sum.add(e.getValue().multiply(x[e.getKey()]));return sum.compareTo(r.upper())<=0;}
 public static void main(String[] args){Random rng=new Random(874678943);long points=0,cuts=0;for(int c=0;c<1000;c++){int n=2+rng.nextInt(9);BigInteger[] lo=new BigInteger[n],hi=new BigInteger[n],plant=new BigInteger[n];ExactRational[] point=new ExactRational[n];for(int i=0;i<n;i++){lo[i]=b(rng.nextInt(4));hi[i]=lo[i].add(BigInteger.ONE);plant[i]=lo[i].add(b(rng.nextInt(2)));point[i]=new ExactRational(lo[i].multiply(b(4)).add(b(rng.nextInt(5))),b(4));}List<ExactLinearProgram.Constraint> rows=new ArrayList<>();BigInteger scale=c%4==0?BigInteger.TEN.pow(40):BigInteger.ONE;for(int k=0;k<2+rng.nextInt(20);k++){Map<Integer,BigInteger> terms=new TreeMap<>();BigInteger rhs=b(rng.nextInt(8)).multiply(scale);for(int i=0;i<n;i++){int v=rng.nextInt(13)-6;if(v!=0){BigInteger a=b(v).multiply(scale);terms.put(i,a);rhs=rhs.add(a.multiply(plant[i]));}}rows.add(new ExactLinearProgram.Constraint(terms,rhs));}PlanningBudget budget=new PlanningBudget(0,20_000_000,64L<<20,()->false,()->0L);var extra=CountProbedCoverHelper.separate(rows,lo,hi,point,budget);cuts+=extra.size();for(int mask=0;mask<(1<<n);mask++){BigInteger[] value=lo.clone();for(int i=0;i<n;i++)if((mask&(1<<i))!=0)value[i]=hi[i];if(rows.stream().anyMatch(row->!pass(row,value)))continue;points++;for(var cut:extra)if(!pass(cut,value))throw new AssertionError("badcut model="+c+" cut="+cut+" at="+Arrays.toString(value));}if(budget.reservedBytes()!=0)throw new AssertionError("leak");}System.out.println("ProbedCoverProbe models=1000 cuts="+cuts+" feasibleIntegerPoints="+points+" invalid=0 leaks=0");}
}
